    || !['assorbimento_completo', 'assorbimento_parziale'].includes(e.protezione)
    || (e.danno_ai_pv === 0) !== (e.protezione === 'assorbimento_completo')
    || e.dopo_urto !== 'sabbia_consumata_ripristino_al_turno_successivo') return false;
