function tagliaAllaFrase(s: string, max: number): string {
  if (s.length <= max) return s;
  const t = s.slice(0, max);
  const p = Math.max(t.lastIndexOf(". "), t.lastIndexOf("! "), t.lastIndexOf("? "));
  return p > 0 ? t.slice(0, p + 1).trim() : "";
}

