Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  if (req.method !== "POST") return json({ error: "method_not_allowed" }, 405);

  const partito = Date.now();
  const ordinaryBudget = new OrdinaryBudget();

  try {
    const url = Deno.env.get("SUPABASE_URL")!;
    const svc = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const admin = createClient(url, svc, { auth: { persistSession: false } });

    const marker = req.headers.get("x-combat-ordinary");
    const privateMarker=req.headers.get("x-user-test-common");
    if(privateMarker!==null&&(privateMarker!=="1"||marker!==null))return json({error:"user_scene_route_invalid"},400);
    const channel = marker === "1" || privateMarker === "1" ? ordinaryRest(url, svc) : null;
    let body: any;
    let authorized = false;
    const tickHeader = req.headers.get("x-tick-token");
    if(privateMarker==="1"){
      if(req.headers.get("authorization")!==`Bearer ${svc}`) return json({error:"unauthorized"},403);
      body=await ordinaryBudget.run("auth",signal=>ordinaryBody(req,signal),{reserveMs:8000});
      if(!body||Array.isArray(body)||Object.keys(body).length!==1||!/^[a-f0-9-]{36}$/i.test(body.user_test_reservation))return json({error:"user_scene_request_invalid"},400);
      authorized=true;
    } else if (marker !== null) {
      if (!channel) return json({ error: "ordinary_route_invalid" }, 400);
      try {
        await ordinaryBudget.run("auth", async signal => {
          body = await ordinaryBody(req, signal);
          if (!body || Array.isArray(body) || !Object.prototype.hasOwnProperty.call(body, "ordinary_round_id")) {
            throw new Error("ordinary_route_invalid");
          }
          if (!tickHeader) return;
          const token = await channel.tickToken(signal);
          authorized = !!token && token === tickHeader;
        }, { reserveMs: 8000 });
      } catch { return json({ error: "ordinary_ingress_unavailable" }, 503); }
    } else {
      body = await req.json().catch(() => ({}));
      if(body && Object.hasOwn(body,"user_test_reservation")) return json({error:"user_scene_route_required"},400);
      // Nessun ordinary senza marker può ricadere nel percorso legacy.
      if (body && Object.prototype.hasOwnProperty.call(body, "ordinary_round_id")) {
        return json({ error: "ordinary_route_required" }, 400);
      }
      // Autorizzazione legacy invariata.
      if (tickHeader) {
        const { data: rt } = await admin.from("academy_ai_runtime").select("tick_token").eq("id", 1).maybeSingle();
        if (rt?.tick_token && tickHeader === rt.tick_token) authorized = true;
      }
    }
    if (!authorized) return json({ error: "unauthorized" }, 403);

    if (channel) {
      const requestFor = (p: any, limits: any) => ({
        braccio: BRACCIO_ATTIVO, modelloConsumer: MODEL_DEFAULT, sistema: p.sys, utente: p.usr,
        maxTokens: limits.maxOutputTokens - BRACCI[BRACCIO_ATTIVO].riserva_ragionamento, temperatura: null,
      });
      const result = await (privateMarker === "1" ? sceneUser : body?.recovery === true ? recoveryOrdinary : sceneOrdinary)(body, channel, {
        startedAt: partito,
        measure: async (p: any, limits: any) => measureResponsePayload(responsePayload(requestFor(p,limits)),limits),
        count: async (payload: any, signal: AbortSignal) => {
          const key=Deno.env.get('OPENAI_API_KEY');if(!key)throw new Error('scene_count_configuration_unavailable');
          const counted=await fetch('https://api.openai.com/v1/responses/input_tokens',{
            method:'POST',signal,headers:{'content-type':'application/json',authorization:`Bearer ${key}`},body:JSON.stringify(payload)});
          if(!counted.ok)throw new Error('scene_count_http_failure');
          return await counted.json();
        },
        generate: (p: any, signal: AbortSignal, onAttempt: () => void, limits: any, permission: any, countBinding: any) => chiamaAdattatore({
          ...requestFor(p,limits), signal,
          fetchImpl: async (input, init) => {
            if (typeof init?.body !== 'string' || new TextEncoder().encode(init.body).length > limits.maxRequestBytes)
              throw new Error('scene_provider_request_overflow');
            if(countBinding && (init.body!==countBinding.payload_text
              ||permission?.generation_request_sha256!==countBinding.generation_request_sha256
              ||await requestSha(init.body)!==countBinding.generation_request_sha256))
              throw new Error('scene_generation_count_bytes_changed');
            if (privateMarker !== '1') {
              if (typeof permission?.quota_required !== 'boolean') throw new Error('scene_quota_contract_incompatible');
              if (permission.quota_required) {
                const method = body?.recovery === true
                  ? 'combat_consumer_recovery_quota_send_v1' : 'combat_consumer_scene_quota_send_v1';
                const sent = await channel.rpc(method, {
                  p_round: body.ordinary_round_id, p_report_sha256: body.report_sha256,
                  p_request_key: body.request_key,
                }, signal);
                if (sent.error || sent.data?.may_send_http !== true)
                  throw new Error('scene_quota_send_denied_or_uncertain');
              }
            }
            onAttempt(); return fetch(input,init);
          },
        }),
        mechanicalCodes: (raw: string, context: any) => typeof raw !== 'string' ? [] :
          violazioni(raw,factsValidationContext(context)).filter(x => x.startsWith('copia colpita incompatibile')).map(() => 'copy_outcome_conflict'),
        audit: (ai: any, delivery: any, diagnostics: any, signal: AbortSignal) => channel.audit({
          ...auditOrchestra(ai ? telemetria(ai) : {}),
          versione_funzione: 'combat-scene-edge/1', versione_prompt: 'narrative-editorial/5+scene-redaction/6+combat-outcome-clarity/3+combat-result-semantics/1',
          versione_repertorio: 'narrative-editorial/5', impronta_prompt: '361e37c02823790a12c5f3e0f385abc60a5e5e0b25fe9be5b1340f461ff109ea', impronta_repertorio: 'dd714bb602a515615b2a4af49af7d068d1c87d6645d376b8f6674581c77f5d0f',
          usage_api: { ...(ai ? telemetria(ai) : {}), ordinary_adapter: 'combat-scene-edge/1',
            validator_revision: 'combat-scene-validator/1', result_status: delivery.status,
            reason_codes: diagnostics.failure_codes, advisories: diagnostics.advisories ?? [],
            provider_request_sha256: delivery.provider_request_sha256 },
          origine_tabella: 'combat_v2_round_reports', origine_id: null,
        },signal),
      });
      return json(result.data, result.status);
    }

    // [046] IL BRACCIO, una volta sola e prima di tutto il resto.
    const preview = !!body?.preview;
    const scelta = braccioRichiesto(body, preview);
    const braccio = scelta.braccio;

    if (body?.ping) {
      const provPing = BRACCI[braccio].provider;
      // I due errori restano DUE, e ciascuno nomina il proprio provider: un
      // legge a controllare la chiave sbagliata.
      if (!Deno.env.get(nomeChiave(provPing))) {
        return json({ error: "missing_openai_key", braccio }, 500);
      }
      const p = await chiamaNarratore(braccio, MODEL_DEFAULT, "Rispondi in italiano.", "Rispondi con una sola parola: pong.", 16);
      if (!p.ok) {
        return json({ error: "openai_error",
                      status: p.status, detail: p.detail, braccio }, 502);
      }
      return json({ ok: true, model: p.model ?? MODEL_DEFAULT, provider: p.provider,
                    braccio, pong: p.text, telemetria: telemetria(p) });
    }

    const session_id = body?.session_id;
    const referto_id = body?.referto_id;
    if (!session_id) return json({ error: "missing_session_id" }, 400);
    if (!referto_id) return json({ error: "missing_referto_id" }, 400);

    const { data: ctx, error: cErr } = await admin.rpc("combat_narratore_context", {
      p_session: session_id,
      p_referto: referto_id,
      p_preview: preview,
    });
    if (cErr) return json({ error: "context_error", detail: cErr.message }, 500);
    if (!ctx || ctx.error) return json({ error: "context", detail: ctx?.error || "no context" }, 400);
    if (ctx.niente_da_raccontare) return json({ skipped: true, reason: "niente da raccontare" });
    if (ctx.gia_narrato) return json({ skipped: true, reason: "già narrato" });

    // ---- [053 · contratto 044] il contesto narrativo -----------------------
    // RPC service-only: porta i fatti autoritativi già risolti e i resoconti
    // dei giocatori legati per UUID e SHA. Se il database non ce l'ha ancora,
    // NON si ripiega sull'ultimo messaggio della stanza e non si inventa
    // niente: si annota nel diario e si racconta come faceva la 049. È il
    // degrado governato dichiarato nella COMPATIBILITA della 049.
    const notaNarrativa: string[] = [];
    const { data: nctx, error: nErr } = await admin.rpc("combat_narrative_context", {
      p_referto: referto_id,
    });
    if (nErr) {
      notaNarrativa.push(`contesto narrativo assente: ${String(nErr.message).slice(0, 120)}`);
    } else if (nctx && !nctx.error) {
      if (sequenzaDi(nctx) === null) {
        notaNarrativa.push(`sequenza sconosciuta «${String(nctx?.sequence).slice(0, 40)}»: contesto narrativo ignorato`);
      } else {
        ctx.narrativo = nctx;
      }
    } else if (nctx?.error) {
      // La RPC del 044 fallisce CHIUSA quando UUID, autore, luogo, sessione o
      // SHA non coincidono. Un fallimento chiuso non è un intoppo da aggirare:
      // è la prova che i messaggi non sono quelli che credevamo.
      notaNarrativa.push(`contesto narrativo rifiutato: ${String(nctx.error).slice(0, 120)}`);
    }

    // [R2] Il ramo si sceglie qui, una volta sola, su `genere`.
    const ramo = scegliRamo(ctx);
    if (ramo.errore) return json({ error: "contratto", detail: ramo.errore }, 400);

    const model = (typeof ctx.model === "string" && ctx.model.trim()) ? ctx.model.trim() : MODEL_DEFAULT;
    if (model !== MODEL_DEFAULT) return json({ error: "model_contract_mismatch" }, 503);
    const { sys, usr } = buildPrompts(ctx);
    // Un referto, una chiamata. Il budget solleva alla seconda.
    const budget = creaBudgetModello(1);

    // ---- UN SOLO tentativo. Il secondo è del cron. ------------------------
    let testo = "";
    const diario: string[] = [];
    // [046] La telemetria confrontabile del piano §3. Resta `null` finché una
    // chiamata non parte davvero: un referto con un provider scritto dentro e
    // zero token direbbe che una chiamata c'è stata quando non c'è stata.
    let tele: Record<string, unknown> | null = null;
    for (const n of notaNarrativa) diario.push(n);
    if (scelta.nota) diario.push(scelta.nota);
    if (ramo.nota) diario.push(ramo.nota);

    // [046] La chiave che conta è quella del PROVIDER DEL BRACCIO.
    const provAttivo = BRACCI[braccio].provider;
    const chiaveBraccio = Deno.env.get(nomeChiave(provAttivo));
    if (!chiaveBraccio) {
      diario.push(`nessuna chiave (${provAttivo})`);
    } else {
      const ac = new AbortController();
      const timer = setTimeout(() => ac.abort(), Math.max(5_000, BUDGET_MS - (Date.now() - partito)));
      let ai: UscitaModello;
      try {
        budget.consuma();
        ai = await chiamaNarratore(braccio, model, sys, usr, 1800, ac.signal);
      } catch (e) {
        ai = { ok: false, detail: String((e as Error)?.message ?? e) };
      } finally {
        clearTimeout(timer);
      }

      tele = telemetria(ai, { versione_adattatore: ADATTATORE_VERSIONE });
      await registraOrchestra(admin, tele, { tabella: "combat_referto", id: String(referto_id) });
      if (!ai.ok) {
        diario.push(`chiamata fallita: ${ai.status ?? ""} ${String(ai.detail).slice(0, 160)}`);
      } else {
        const grezzo = toSingleBlock(ai.text || "");
        const male = violazioni(grezzo, ctx);
        if (male.length) {
          diario.push(`scartato (${male.join(", ")})`);
        } else {
          const tagliato = tagliaAllaFrase(grezzo, LUNG_MAX);
          if (tagliato.length === 0) {
            diario.push(`scartato: nessuna frase chiusa entro ${LUNG_MAX}`);
          } else if (tagliato.length < LUNG_MIN) {
            diario.push(`scartato dopo il taglio (${tagliato.length} < ${LUNG_MIN})`);
          } else {
            testo = tagliato;
            diario.push(`accettato (${testo.length} caratteri)`);
          }
        }
      }
    }

    if (preview) {
      return json({
        ok: true, genere: ramo.genere, preview: testo || ripiego053(ctx) || ripiego(ctx),
        vuoto: testo.length === 0, chiamate_modello: budget.quante(), diario, model,
        braccio, telemetria: tele, nota_braccio: scelta.nota ?? null,
      });
    }

    // ---- apply viene chiamata SEMPRE --------------------------------------
    // Con testo → pubblica. Senza testo → è un tentativo fallito: apply
    // incrementa narr_tentativi e, se è il secondo, scrive il ripiego e
    // chiude. Le stringhe del ripiego restano a database, non qui.
    const { data: applied, error: aErr } = await admin.rpc("combat_narratore_apply", {
      p_referto: referto_id,
      p_testo: testo.length ? testo : null,
      p_fallback: false,
    });
    if (aErr) return json({ error: "apply_error", detail: aErr.message, diario }, 500);

    return json({
      ok: true, genere: ramo.genere, posted: testo || null,
      tentativo_fallito: testo.length === 0, chiamate_modello: budget.quante(),
      diario, applied, model, braccio, telemetria: tele,
    });
  } catch (e) {
    // Anche qui: il gioco è già salvato e avanzato. Non si rompe niente.
    return json({ error: "server_error", detail: String((e as Error)?.message ?? e) }, 500);
  }
});

import {scenePrompts, inspectNarrative, EDGE_REVISION, VALIDATOR_REVISION} from './editorial.mjs';
import {canonical, digest} from './scene.mjs';

export const LIFECYCLE_VERSION = 'combat-narrative-lifecycle/1';
const uncertain = phase => ({state: 'uncertain', phase, provider_retry_allowed: false});
const known = new Set(['claimed', 'provider_reserved', 'generated', 'published', 'failed']);
function matches(record, request) {
  return record && record.schema_version === LIFECYCLE_VERSION
    && record.request_key === request.request_key && record.round_id === request.round_id
    && record.report_sha256 === request.report_sha256 && known.has(record.state);
}
// Adapter proposto: tutte le operazioni DB sono autenticate, bounded e atomiche.
// acquire non autorizza il provider; reserve concede un solo granted_now.
// persist è idempotente per chiave+hash; publish usa SOLO il risultato persistito.
export async function runSceneNarrative(request, d) {
  if (!request || Object.keys(request).length !== 3 || !['request_key', 'round_id', 'report_sha256'].every(k => typeof request[k] === 'string')
    || !/^[a-f0-9]{64}$/.test(request.report_sha256)) return {state: 'rejected', phase: 'ingress'};
  const observe = async () => {
    try { const r = await d.phase('status', signal => d.status(request, signal)); return matches(r, request) ? r : null; }
    catch (e) { if ((e?.message === 'scene_contract_incompatible' || e?.message === 'scene_count_contract_incompatible')) return {incompatible: true}; return null; }
  };
  let record;
  try { record = await d.phase('claim', signal => d.acquire(request, signal)); }
  catch (e) { if ((e?.message === 'scene_contract_incompatible' || e?.message === 'scene_count_contract_incompatible')) return {state: 'rejected', phase: 'contract'}; }
  if (!matches(record, request)) record = await observe();
  if (record?.incompatible) return {state: 'rejected', phase: 'contract'};
  if (!record) return uncertain('claim');
  if (record.state === 'published' || record.state === 'failed') return {state: record.state, completion: record.completion};
  if (record.state === 'provider_reserved') return uncertain('provider_authorization');
  async function publish() {
    try {
      const r = await d.phase('publish', signal => d.publish(request, signal));
      if (matches(r, request) && r.state === 'published') return {state: 'published', completion: r.completion};
    } catch { /* nessuna rigenerazione per una ricevuta persa */ }
    const r = await observe();
    return r?.state === 'published' ? {state: 'published', completion: r.completion, reconciled: true} : uncertain('publication');
  }
  if (record.state === 'generated') return publish();
  if (record.edge_revision !== EDGE_REVISION || record.validator_revision !== VALIDATOR_REVISION)
    return {state: 'rejected', phase: 'version'};
  let prompts;
  try {
    prompts = await scenePrompts(record.scene, record.binding, d.limits);
    if (record.binding.round_id !== request.round_id || record.binding.report_sha256 !== request.report_sha256)
      throw new Error('request_binding_changed');
    // Misura il payload EFFETTIVO dell'adattatore, incluse istruzioni e busta API.
    await d.checkProviderBudget(prompts);
  } catch { return {state: 'rejected', phase: 'context_or_budget'}; }
  let permission;
  try {
    permission = await d.phase('reserve', signal => d.reserve(request, {
      snapshot_sha256: record.scene.snapshot_sha256, control_version: record.binding.control_version,
    }, signal));
  } catch { return uncertain('provider_authorization'); }
  if (!matches(permission, request) || permission.state !== 'provider_reserved' || permission.granted_now !== true)
    return uncertain('provider_authorization');
  let attempts = 0;
  const onAttempt = () => { if (attempts !== 0) throw new Error('second_provider_forbidden'); attempts = 1; };
  let result;
  try {
    const ai = await d.phase('provider', signal => d.generate(prompts, signal, onAttempt, permission));
    const provenance = ai && ai.provider === 'openai' && ai.model === 'gpt-6-luna'
      && attempts === 1 && ai.http_attempts === 1 && typeof ai.response_id === 'string' && ai.response_id.length > 0
      && /^[a-f0-9]{64}$/.test(ai.request_sha256) && /^[a-f0-9]{64}$/.test(ai.raw_sha256)
      && Number.isSafeInteger(ai.input_tokens) && ai.input_tokens >= 0 && Number.isSafeInteger(ai.output_tokens) && ai.output_tokens > 0;
    const inspection = inspectNarrative(ai?.text, {providerComplete: ai?.complete === true, ...d.limits,
      mechanicalCodes: await d.mechanicalCodes(ai?.text, record.scene.snapshot)});
    result = {status: provenance && inspection.text ? 'succeeded' : 'failed', text: provenance ? inspection.text : null,
      failure_codes: [...inspection.codes, ...(!provenance ? ['provider_provenance_invalid'] : [])],
      advisories: inspection.advisories, http_attempts: attempts,
      provider: 'openai', model: 'gpt-6-luna', response_id: provenance ? ai.response_id : null,
      request_sha256: provenance ? ai.request_sha256 : null, raw_sha256: provenance ? ai.raw_sha256 : null,
      input_tokens: provenance ? ai.input_tokens : null, output_tokens: provenance ? ai.output_tokens : null};
  } catch { result = {status: 'failed', text: null, failure_codes: ['provider_or_validation_uncertain'], http_attempts: attempts}; }
  const succeeded = result.status === 'succeeded';
  const delivery = {schema_version: 'ordinary-narrative-result/2', status: result.status,
    report_sha256: request.report_sha256, context_sha256: record.scene.snapshot_sha256,
    control_version: record.binding.control_version, edge_revision: EDGE_REVISION, validator_revision: VALIDATOR_REVISION,
    text: succeeded ? result.text : null, text_sha256: succeeded ? await digest(result.text) : null,
    validation_passed: succeeded, provider: 'openai', model: 'gpt-6-luna',
    provider_response_id: result.response_id ?? null, provider_request_sha256: result.request_sha256 ?? null,
    raw_output_sha256: result.raw_sha256 ?? null, input_tokens: result.input_tokens ?? null, output_tokens: result.output_tokens ?? null,
    http_attempts: result.http_attempts, failure_code: succeeded ? null : 'provider_error'};
  const resultHash = await digest(canonical(delivery));
  let stored;
  try { stored = await d.phase('persist', signal => d.persist(request, delivery, resultHash, signal)); } catch { /* status soltanto */ }
  if (!matches(stored, request) || stored.result_sha256 !== resultHash) stored = await observe();
  if (!stored || stored.result_sha256 !== resultHash) return {...uncertain('delivery'), result_sha256: resultHash};
  // Usage/provenienza sono già durevoli nel risultato; errore audit secondario non elimina il Fato.
  if (d.audit) { try { await d.phase('audit', signal => d.audit(delivery, result, signal)); } catch { /* nessuna rigenerazione */ } }
  if (stored.state === 'failed') return {state: 'failed', completion: stored.completion};
  if (stored.state === 'published') return {state: 'published', completion: stored.completion};
  return stored.state === 'generated' ? publish() : uncertain('delivery');
}

import repertorio from "./repertorio.json" with { type: "json" };

const CONSUMER = "combat_narratore_ai";
export function caricaOrchestra() {
  if (repertorio.consumer !== CONSUMER || !repertorio.prompt || !repertorio.impronta_prompt) throw new Error("repertorio_assente_o_incoerente");
  return Object.freeze(repertorio);
}
export function auditOrchestra(usage: unknown) {
  const r = caricaOrchestra();
  return { modello: r.parametri_modello.modello, versione_funzione: r.versione_funzione, versione_deploy: null, versione_prompt: r.versione_prompt, versione_repertorio: r.versione_repertorio, impronta_prompt: r.impronta_prompt, impronta_repertorio: r.impronta_repertorio, consumer: r.consumer, dominio: r.dominio, parametri_modello: r.parametri_modello, usage_api: usage };
}
export async function registraOrchestra(admin: any, usage: unknown, origine: { tabella?: string; id?: string } = {}) {
  const riga = { ...auditOrchestra(usage), origine_tabella: origine.tabella ?? null, origine_id: origine.id ?? null };
  const { error } = await admin.from("ai_orchestra_audit").insert(riga);
  if (error) throw new Error("audit_orchestra_non_registrato: " + error.message);
}

// Candidato OFFLINE: nessun ripiego legacy, una sola chiamata per claim.
import type { UscitaModello } from "./adattatore.ts";
import { OrdinaryBudget, OrdinaryTimeout } from "./transport.ts";
import { factsContext, FACTS_EDGE, factsValidatorRevision } from './facts.ts';
import { rinunciaContext, RINUNCIA_EDGE, RINUNCIA_VALIDATOR } from "./rinuncia.ts";
import { diagnosticRecord, type TextInspection } from "./diagnostics.ts";

type Rpc = (name: string, args: Record<string, unknown>, signal: AbortSignal) => PromiseLike<{ data: any; error: unknown }>;
type Dependencies = {
  rpc: Rpc;
  prompts: (context: any) => { sys: string; usr: string };
  call: (sys: string, usr: string, signal: AbortSignal, onAttempt: () => void) => Promise<UscitaModello>;
  validate: (text: string, context: any) => TextInspection;
  audit: (ai: UscitaModello, reportId: string, signal: AbortSignal, diagnostics: Awaited<ReturnType<typeof diagnosticRecord>>) => Promise<void>;
  budget?: OrdinaryBudget;
};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const sha = /^[a-f0-9]{64}$/;
const tokenCount = (n: unknown): n is number => Number.isSafeInteger(n) && (n as number) >= 0;
const digest = async (s: string) => Array.from(new Uint8Array(
  await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s)),
)).map((n) => n.toString(16).padStart(2, "0")).join("");

export async function ordinary(body: any, d: Dependencies): Promise<{ status: number; data: Record<string, unknown> }> {
  const budget = d.budget ?? new OrdinaryBudget();
  const keys = ["ordinary_round_id", "report_sha256", "request_key"];
  if (!body || Object.keys(body).length !== keys.length || keys.some((k) => typeof body[k] !== "string")
    || !uuid.test(body.ordinary_round_id) || !uuid.test(body.request_key) || !sha.test(body.report_sha256)) {
    return { status: 400, data: { error: "ordinary_request_invalid" } };
  }
  async function status(claimId: string | null) {
    try {
      const r = await budget.run("status", signal => d.rpc("combat_consumer_narrative_status_v1", {
        p_round: body.ordinary_round_id, p_report_sha256: body.report_sha256,
        p_request_key: body.request_key, p_claim: claimId,
      }, signal));
      return r.error ? null : r.data;
    } catch { return null; }
  }
  let claimed;
  try {
    claimed = await budget.run("claim", signal => d.rpc("combat_consumer_narrative_claim_v1", {
      p_round: body.ordinary_round_id, p_report_sha256: body.report_sha256, p_request_key: body.request_key,
    }, signal), { reserveMs: 8000 });
  } catch { claimed = { data: null, error: "uncertain" }; }
  if (claimed.error || !claimed.data) {
    const observed = await status(null);
    return { status: 503, data: { error: "ordinary_claim_unavailable", state: observed?.state ?? "unknown" } };
  }
  const c = claimed.data;
  if (c.should_call_provider !== true) {
    return { status: 200, data: { skipped: true, state: c.state, completion: c.completion ?? null } };
  }
