    const started = performance.now();
    const finiteCaps: Record<string,number> = {count_start:2000,count:8000,count_finish:3000,persist:4000,publish:3000,audit:1000};
    const finiteReserves: Record<string,number> = {count_start:23000,count:15000,count_finish:12000,reserve:8000,provider:8000,persist:4000,publish:1000,audit:0};
    const reserve = this.financial ? (finiteReserves[phase] ?? reserves[phase] ?? 0) : (reserves[phase] ?? 0);
    const cap = this.financial ? (finiteCaps[phase] ?? caps[phase] ?? 0) : (caps[phase] ?? 0);
    const leaseBound = ['reserve', 'provider', 'persist', 'count_start', 'count', 'count_finish'].includes(phase) ? this.leaseDeadline : Infinity;
    const ms = Math.min(cap, this.deadline - started - reserve, leaseBound - started - reserve);
    if (!Number.isFinite(ms) || ms <= 0) throw new Error('scene_budget_exhausted');
