    persist: (_: any, p: any, _hash: string, signal: AbortSignal) => rpc('combat_consumer_scene_save_v2', {p_result_text: canonical(p)}, signal),
    publish: (_: any, signal: AbortSignal) => rpc('combat_consumer_scene_complete_v2', {}, signal),
