}
export async function verifyScene(envelope, binding) {
  if (!exact(envelope, ['snapshot', 'snapshot_sha256']) || !sha(envelope.snapshot_sha256)) throw new Error('scene_envelope_invalid');
  const s = envelope.snapshot;
  const privateTest=s?.schema_version==='user-test-scene/1';
  if (privateTest && (s.surface!=='user_test'||s.visibility!=='owner_private'||binding.surface!==s.surface||binding.visibility!==s.visibility||binding.session_id!==s.session_id)) throw new Error('scene_private_binding_invalid');
  if (!exact(s, ['schema_version', 'session_id', 'round_id', 'report_sha256', 'control_version', 'location', 'actors', 'actions', 'resolved_facts', 'sources', 'selection', ...(privateTest ? ['surface','visibility'] : [])])
    || s.schema_version !== (privateTest ? 'user-test-scene/1' : SCENE_VERSION) || !exact(s.selection, ['max_input_bytes', 'previous_available', 'previous_included']))
    throw new Error('scene_version_invalid');
  const {schema_version, sources, selection, surface=null, visibility=null, ...header} = s;
  for (const k of ['session_id', 'round_id', 'report_sha256', 'control_version'])
    if (header[k] !== binding[k]) throw new Error('scene_binding_changed');
  if (binding.hash_authority === 'combat_v2_sha256/jsonb') {
    // Solo envelope della RPC autenticata. L'hash DB è opaco, non è JSON.stringify.
    if (binding.scene_sha256 !== envelope.snapshot_sha256) throw new Error('scene_hash_changed');
  } else if (await digest(canonical(s)) !== envelope.snapshot_sha256) throw new Error('scene_hash_changed');
  const rebuilt = await buildScene(header, sources, {maxInputBytes: selection.max_input_bytes, surface, visibility});
  if (!Number.isSafeInteger(selection.previous_available) || selection.previous_available < selection.previous_included
    || selection.previous_included !== sources.filter(s => s.kind === 'fato').length
    || canonical(rebuilt.snapshot.sources) !== canonical(sources)) throw new Error('scene_selection_invalid');
  return structuredClone(s);
}

// Solo ordinary. Abort interrompe l'attesa/HTTP locale, non prova rollback remoto.
export class OrdinaryTimeout extends Error {
  constructor(readonly phase: string) { super("ordinary_transport_timeout"); }
}
export type OrdinaryPhase = "auth" | "claim" | "model" | "audit" | "complete" | "status";
const caps: Record<OrdinaryPhase, number> = {
  auth: 3000, claim: 3000, model: 45000, audit: 3000,
  complete: 3000, status: 2000, // 5s riserva consegna = 3s invio + 2s riconciliazione.
};
export class OrdinaryBudget {
  private readonly deadline: number;
  constructor(private readonly now: () => number = () => performance.now(), durationMs = 50000) {
    this.deadline = now() + durationMs;
  }
  remaining(): number { return Math.max(0, this.deadline - this.now()); }
  async run<T>(phase: OrdinaryPhase, fn: (signal: AbortSignal) => PromiseLike<T>,
    options: { reserveMs?: number; leaseRemainingMs?: number; capMs?: number } = {}): Promise<T> {
    const reserve = options.reserveMs ?? 0;
    const ms = Math.min(caps[phase], options.capMs ?? Infinity,
      this.remaining() - reserve, (options.leaseRemainingMs ?? Infinity) - reserve);
    if (!Number.isFinite(ms) || ms <= 0) throw new OrdinaryTimeout(phase);
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const timeout = new Promise<never>((_, reject) => {
      timer = setTimeout(() => {
        controller.abort();
        reject(new OrdinaryTimeout(phase));
      }, ms);
    });
    try {
      // Il segnale deve essere passato a fetch/abortSignal del builder dal chiamante.
      // race dà un bound anche se il peer risponde dopo l'abort: nessun retry qui.
      return await Promise.race([Promise.resolve().then(() => fn(controller.signal)), timeout]);
    } finally {
      if (timer !== undefined) clearTimeout(timer);
    }
  }
}

// Lettura abortibile: il marker sceglie il ramo, non autorizza la richiesta.
export async function ordinaryBody(req: Request, signal: AbortSignal): Promise<unknown> {
  if (!req.body) return null;
  const reader = req.body.getReader();
  const abort = () => { void reader.cancel().catch(() => {}); };
  signal.addEventListener("abort", abort, { once: true });
  const decoder = new TextDecoder();
  let text = "";
  try {
    while (true) {
      if (signal.aborted) throw new OrdinaryTimeout("auth");
      const chunk = await reader.read();
      if (signal.aborted) throw new OrdinaryTimeout("auth");
      if (chunk.done) break;
      text += decoder.decode(chunk.value, { stream: true });
    }
    text += decoder.decode();
    return JSON.parse(text);
  } finally { signal.removeEventListener("abort", abort); reader.releaseLock(); }
}

export function ordinaryRest(url: string, key: string, fetcher: typeof fetch = fetch) {
  const request = async (path: string, method: string, payload: unknown, signal: AbortSignal) => {
    // Una fetch reale per operazione; nessun wrapper SDK o retry implicito.
    const response = await fetcher(url.replace(/\/$/, "") + "/rest/v1/" + path, {
      method, signal, headers: { apikey: key, Authorization: "Bearer " + key,
        "Content-Type": "application/json", Prefer: path.startsWith("rpc/") ? "return=representation" : "return=minimal" },
      body: payload === undefined ? undefined : JSON.stringify(payload),
    });
    if (!response.ok) return { data: null, error: "ordinary_http_" + response.status };
    const text = await response.text();
    return { data: text ? JSON.parse(text) : null, error: null };
  };
  return {
    async tickToken(signal: AbortSignal) {
      const r = await request("academy_ai_runtime?select=tick_token&id=eq.1", "GET", undefined, signal);
      return r.error || !Array.isArray(r.data) || r.data.length !== 1 ? null : r.data[0].tick_token;
    },
    rpc(name: string, args: Record<string, unknown>, signal: AbortSignal) {
      if (!["combat_consumer_narrative_claim_v1", "combat_consumer_narrative_complete_v1",
        "combat_consumer_narrative_status_v1", "combat_consumer_scene_acquire_v2", "combat_consumer_scene_permit_v3",
        "combat_consumer_scene_status_v2", "combat_consumer_scene_save_v2", "combat_consumer_scene_complete_v2",
        "combat_consumer_scene_quota_send_v1", "combat_consumer_recovery_acquire_v1",
        "combat_consumer_recovery_permit_v2", "combat_consumer_recovery_status_v1",
        "combat_consumer_recovery_save_v1", "combat_consumer_recovery_complete_v1",
        "combat_consumer_recovery_quota_send_v1", "combat_consumer_count_start_v1", "combat_consumer_count_finish_v1"].includes(name)) throw new Error("ordinary_rpc_not_allowed");
      return request("rpc/" + name, "POST", args, signal);
    },
    async audit(row: unknown, signal: AbortSignal) {
      const r = await request("ai_orchestra_audit", "POST", row, signal);
      if (r.error) throw new Error("ordinary_audit_uncertain");
    },
  };
}

import {runSceneNarrative} from './lifecycle.mjs';
import {canonical} from './scene.mjs';
import {EDGE_REVISION,VALIDATOR_REVISION} from './editorial.mjs';
import {SceneBudget} from './runtime.ts';
export async function sceneUser(body, channel, options) {
  if (!body || Object.keys(body).length!==1 || !/^[a-f0-9-]{36}$/i.test(body.user_test_reservation)) return {status:400,data:{error:'user_scene_request_invalid'}};
  const budget=new SceneBudget(50000-(Date.now()-options.startedAt));
  const bindingResponse=await budget.run('status', signal=>channel.rpc('test_room_user_ai_binding_v2',{p_reservation:body.user_test_reservation},signal));
  if(bindingResponse.error||!bindingResponse.data) return {status:503,data:{error:'user_scene_binding_unavailable'}};
  const b=bindingResponse.data;
  const request={round_id:b.round_id,report_sha256:b.report_sha256,request_key:b.request_key};
  const rpc=async(name,extra,signal)=>{const r=await channel.rpc(name,{p_reservation:body.user_test_reservation,...extra},signal);if(r.error||!r.data)throw new Error('scene_rpc_uncertain');return r.data;};
  const limits = {transportMaxChars: 5000, maxInputBytes: 49152, maxRequestBytes: 65536, maxOutputTokens: 9992};
  const checkedRecord = (r) => {
    if (!r.limits || Object.keys(r.limits).length !== Object.keys(limits).length
      || Object.entries(limits).some(([k,v]) => r.limits[k] !== v)
      || r.scene?.snapshot?.selection?.max_input_bytes !== limits.maxInputBytes)
      throw new Error('scene_contract_incompatible');
    return r;
  };
  let aiUsage;
  const result = await runSceneNarrative(request, {
    limits, phase: (p, fn) => budget.run(p, fn),
    acquire: async (_, signal) => {
      return checkedRecord(await rpc('test_room_user_scene_acquire_v2', {}, signal));
    },
    status: async (_, signal) => checkedRecord(await rpc('test_room_user_scene_status_v2', {}, signal)),
    reserve: (_, b, signal) => rpc('test_room_user_scene_permit_v2', {p_scene_sha256: b.snapshot_sha256, p_control_version: b.control_version}, signal),
    persist: (_, p, _hash, signal) => rpc('test_room_user_scene_save_v2', {p_result_text: canonical(p)}, signal),
    publish: (_, signal) => rpc('test_room_user_scene_complete_v2', {}, signal),
    checkProviderBudget: async (p) => options.measure(p, limits),
    generate: async (p, signal, onAttempt) => {
      const ai = await options.generate(p, signal, onAttempt, limits); aiUsage = ai;
      return {provider: ai.provider, model: ai.model, http_attempts: ai.tentativi_http, response_id: ai.provider_response_id,
        request_sha256: ai.provider_request_sha256, raw_sha256: ai.raw_output_sha256,
        input_tokens: ai.input_tokens, output_tokens: ai.output_tokens, text: ai.text,
        complete: ai.ok === true && ai.stop_reason === 'end_turn' && ai.troncato !== true};
    },
    mechanicalCodes: (raw, snapshot) => options.mechanicalCodes(raw, JSON.parse(snapshot.resolved_facts)),
    audit: (delivery, diagnostics, signal) => options.audit(aiUsage, delivery, diagnostics, signal),
  });
  return {status: result.state === 'published' || result.state === 'failed' ? 200 : 503,
    data: {...result, edge_revision: EDGE_REVISION, validator_revision: VALIDATOR_REVISION}};
}
